-- COMMAND ----------

-- Read the source and add lineage columns to every row.
CREATE OR REPLACE TEMPORARY VIEW source_raw AS
SELECT
  *,
  _metadata.file_path AS _source_file,
  current_timestamp() AS _ingested_at
FROM read_files(
  's3://vendor-imports/customer-data/',
  format => 'csv',
  header => true,
  delimiter => ',',
  inferSchema => true
);

-- COMMAND ----------

-- All checks run BEFORE the table is replaced, so a bad snapshot never reaches consumers.
DECLARE OR REPLACE VARIABLE rows_loaded BIGINT DEFAULT 0;
SET VAR rows_loaded = (SELECT COUNT(*) FROM source_raw);

-- DQ: completeness. Guard against empty or truncated source exports.
SELECT raise_error(concat('DQ check failed: only ', CAST(n AS STRING),
                          ' rows, expected >= 1000'))
FROM (SELECT rows_loaded AS n)
WHERE n < 1000;

-- DQ: no rows the reader could not parse (they land in _rescued_data instead of failing).
SELECT raise_error(concat('DQ check failed: unparseable rows in _rescued_data (', CAST(n AS STRING), ')'))
FROM (SELECT COUNT(*) AS n FROM source_raw WHERE _rescued_data IS NOT NULL)
WHERE n > 0;

-- DQ: primary key (customer_id) must not be NULL.
SELECT raise_error(concat('DQ check failed: NULL primary key (customer_id) (', CAST(n AS STRING), ')'))
FROM (SELECT COUNT(*) AS n FROM source_raw WHERE customer_id IS NULL)
WHERE n > 0;

-- DQ: uniqueness of the primary key.
SELECT raise_error(concat('DQ check failed: duplicate primary keys (', CAST(n AS STRING), ')'))
FROM (SELECT COUNT(*) AS n FROM (SELECT 1 FROM source_raw GROUP BY customer_id HAVING COUNT(*) > 1))
WHERE n > 0;

-- COMMAND ----------

-- Atomic swap. Delta keeps the previous version: roll back with
--   RESTORE TABLE production.analytics.dim_customer TO VERSION AS OF <n>
CREATE OR REPLACE TABLE production.analytics.dim_customer
AS SELECT * EXCEPT (_rescued_data) FROM source_raw;

-- COMMAND ----------

-- Audit: one row per successful run.
CREATE TABLE IF NOT EXISTS production.analytics._load_audit (
  bundle_name STRING,
  bundle_version STRING,
  table_name STRING,
  loaded_at TIMESTAMP,
  rows_loaded BIGINT,
  status STRING
);

